  const sealedHeaders = (sealed: string, via: "cookie" | "header") =>
    via === "cookie"
      ? { Cookie: `h3-rot=${encodeURIComponent(sealed)}` }
      : { "x-h3-rot-session": sealed };

  // Seals a session with `oldPassword`, as it was before the rotation
  async function sealWithOld(config: SessionConfig = oldConfig): Promise<string> {
    t.app.get("/rot-seed-old", async (event) => {
      await updateSession(event, config, { user: "alice" });
      return "ok";
    });
    const res = await t.fetch("/rot-seed-old");
    return cookieValue(sessionCookie(res)!);
  }

