    const sealed = await sealWithOld();
    t.app.get("/rot-read-no-extra", async (event) => {
      const session = await getSession(event, { ...newConfig, extraUnsealPasswords: undefined });
      return { id: session.id, data: session.data };
    });

    const res = await t.fetch("/rot-read-no-extra", { headers: sealedHeaders(sealed, "cookie") });
    expect(await res.json()).toEqual({ id: "rot-new", data: {} });
  });

