      await expect(unseal(resealedValue, oldPassword, sealDefaults)).rejects.toThrow(
        "Bad hmac value",
      );
      expect(await unseal(resealedValue, newPassword, sealDefaults)).toMatchObject({
        id: "rot-old",
        data: { user: "alice" },
      });
    } finally {
      vi.useRealTimers();
    }
  });

  it("migrates a legacy 1-iteration session sealed with an extra password", async () => {
    const legacySealed = await seal(
      { id: "legacy", createdAt: Date.now(), data: { user: "carol" } },
