      const sealed = await sealWithOld();
      t.app.get("/rot-invalid", async (event) => {
        try {
          await getSession(event, { ...newConfig, extraUnsealPasswords: [bad] });
          return { error: null };
        } catch (error) {
          return { error: (error as Error).message };
        }
      });

