      try {
        const res = await t.fetch("/rot-invalid", { headers: sealedHeaders(sealed, "cookie") });
        expect(await res.json()).toEqual({
          error:
            "Invalid extraUnsealPasswords[0]: must be a string of at least 32 characters",
        });
        // The cookie was never opened
        expect(deriveBits).not.toHaveBeenCalled();
      } finally {
        deriveBits.mockRestore();
      }
    });
  }

