    t.app.get("/rot-write-new", async (event) => {
      await updateSession(event, newConfig, { user: "dave" });
      return "ok";
    });
    const write = await t.fetch("/rot-write-new");
    const sealed = cookieValue(sessionCookie(write)!);

    t.app.get("/rot-cpu", async (event) => {
      const session = await getSession(event, {
        ...newConfig,
        extraUnsealPasswords: [oldPassword, thirdPassword],
      });
